"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def maxSubarraySum(arr):
    maxEndingHere = 0
    maxSoFar = float('-inf')
    for num in arr:
        maxEndingHere = max(num, (maxEndingHere + num))
        maxSoFar = max(maxSoFar, maxEndingHere)
    return maxSoFar
